// ── mountGear — the ONE way a gear gets onto a head (Sum 2026-08-28: "move the gear to far
//    right like it is in the apps top bar"). Same convention as the top bar (topbar.css .tb-spacer):
//    gear = the OUTERMOST right control, past STOP, set apart by a little space. The .card-gearbox
//    wrap carries the whole convention in CSS (desk.css): the far-right seat, the set-apart gap,
//    AND the squeeze rule — on a narrow head the gearbox shrinks away FIRST so STOP survives
//    (Sum: "on min width, hides settings before kill"). Every gear goes through here — makeCard's
//    gear: param, makeSettings, appCard — so no card can scatter the seat again.
window.mountGear = function (head, node) {
  if (!head || !node) return node
  const box = document.createElement('span')
  box.className = 'card-gearbox'
  // the box carries the click-guards, so a gear press never folds or drags the card — the same
  // mousedown+click stops every gear used to carry itself (settings.js, app-card.js; those keep
  // theirs, harmlessly doubled). A gear mounted here needs NO guard of its own (AIOLI's doesn't).
  box.addEventListener('mousedown', e => e.stopPropagation())
  box.addEventListener('click', e => e.stopPropagation())
  box.appendChild(node)
  head.appendChild(box)
  return node
}

