// drag a wing card's edge handle to resize it — width on a side wing, height on top/bottom.
// mirrors workspace.js wireResize, but self-contained (no bot-geo store to pollute).
function wireCardResize(card, handle) {
  handle.addEventListener('mousedown', e => {
    e.preventDefault(); e.stopPropagation()
    const edge = card.dataset.edge
    if (!edge || edge === 'center') return                          // only a wing card resizes
    const horizontal = (edge === 'left' || edge === 'right')
    const sign = (edge === 'left' || edge === 'top') ? 1 : -1        // handle sits on the INNER edge → drag toward the wall grows it
    const start = horizontal ? e.clientX : e.clientY
    const startSize = horizontal ? card.offsetWidth : card.offsetHeight
    const min = horizontal ? 280 : 140
    document.body.style.cursor = horizontal ? 'col-resize' : 'row-resize'
    document.body.style.userSelect = 'none'
    document.body.classList.add('resizing')                         // kill iframe pointer-events so an open card's iframe can't swallow the drag
    const onMove = ev => {
      const delta = (horizontal ? ev.clientX : ev.clientY) - start
      const max = (horizontal ? window.innerWidth : window.innerHeight) * 0.7
      card.style.setProperty('--ab-size', Math.max(min, Math.min(max, startSize + sign * delta)) + 'px')
    }
    const onUp = () => { document.removeEventListener('mousemove', onMove); document.removeEventListener('mouseup', onUp); document.body.style.cursor = ''; document.body.style.userSelect = ''; document.body.classList.remove('resizing') }
    document.addEventListener('mousemove', onMove)
    document.addEventListener('mouseup', onUp)
  })
}

// icon — emoji · png · {css}
function mkIcon(icon) {
  if (icon && typeof icon === 'object' && icon.css) return htmlNode(`<span class="card-icon">${icon.css}</span>`)
  if (typeof icon === 'string' && /\.(png|svg|jpe?g|webp)$/i.test(icon)) return htmlNode(`<img class="card-icon-img" src="${icon}" alt="">`)
  return htmlNode(`<span class="card-icon">${icon}</span>`)
}

// jewels — green/amber/red. setJewel(card, state) drives them + the stop's enabled state.
window.setJewel = function (card, state) {   // 'running' | 'waiting' | 'done' | 'off'
  if (!card) return
  card.querySelectorAll('.cj').forEach(j => j.classList.remove('lit', 'blink'))
  const g = card.querySelector('.cj-g'), a = card.querySelector('.cj-a'), stop = card.querySelector('.card-stop')
  if (state === 'running') { g && g.classList.add('lit', 'blink'); stop && (stop.disabled = false) }
  else if (state === 'waiting') { a && a.classList.add('lit'); stop && (stop.disabled = false) }
  else if (state === 'done') { g && g.classList.add('lit'); stop && (stop.disabled = true) }
  else { stop && (stop.disabled = true) }
  if (stop) stop.classList.toggle('armed', !stop.disabled)   // glow red only when there's a live run to halt
}

// the big fat red STOP — halt the run, salvage what's there. an OCTAGON (stop-sign) icon so it reads as HALT,
// not a random square; dark at rest, glows red while a run is live (.armed, driven by setJewel/barJewel).
function mkStop(card, handler) {
  const b = htmlNode('<button class="card-stop" title="stop — keep what\'s done"><svg class="stop-glyph" viewBox="0 0 24 24" width="14" height="14" fill="currentColor" aria-hidden="true"><path d="M7.9 2h8.2L22 7.9v8.2L16.1 22H7.9L2 16.1V7.9z"/></svg></button>')
  b.addEventListener('mousedown', e => e.stopPropagation())   // press the halt without collapsing/dragging the bar
  b.addEventListener('click', e => {
    e.stopPropagation()
    // (Sum 2026-07-09) a green ask blinking for this bot? RED = DENY it. otherwise RED = halt the live run.
    const bot = card.dataset && card.dataset.agent
    if (bot && window.OZ_HIL && window.OZ_HIL.count && window.OZ_HIL.count(bot) > 0) { window.OZ_HIL.deny(bot); return }
    handler(card)
  })
  return b
}

// the bottom bar — drag to resize THIS card's body (independent). the desk scrolls to find it.
function mkBottom(body, look) {
  const bar = document.createElement('div')
  bar.className = 'card-bottom'; bar.title = 'drag to resize'
  if (typeof look === 'string' && /\.(png|svg|jpe?g|webp)$/i.test(look)) bar.style.backgroundImage = `url('${look}')`
  bar.addEventListener('mousedown', e => {
    e.preventDefault(); e.stopPropagation()
    // GLOBAL DESK RULE (Sum): drag to the bottom and KEEP GOING — the desk auto-scrolls for more room and the
    // card grows as tall as you pull it (a book, a long note, a feed of your own work). the room is the desk's
    // scroll; we reveal it live. height = pointer delta + however far the desk auto-scrolled while you dragged.
    const scroller = body.closest('#card-stack') || document.scrollingElement || document.documentElement
    const sy = e.clientY, sh = body.offsetHeight, startScroll = scroller.scrollTop
    let lastY = e.clientY, curH = sh, raf = 0
    document.body.style.userSelect = 'none'
    document.body.classList.add('resizing')   // CSS kills iframe pointer-events so an iframe body (woodshop · preview) can't swallow the drag → mouseup always lands → no stuck resize
    // the height the gesture is ASKING for: pointer delta + however far the desk auto-scrolled while you dragged.
    const target = () => Math.max(120, sh + (lastY - sy) + (scroller.scrollTop - startScroll))
    const tick = () => {                       // while the pointer rides an edge, scroll the desk + grow with it
      // 1) ride-an-edge auto-scroll — gentle PROPORTIONAL ramp (not a hard on/off): ~0 at the threshold, eases up
      //    the deeper you push, capped low so it never bolts. (was a flat 16px/frame the instant you crossed.)
      const r = scroller.getBoundingClientRect(), margin = 44, MAX = 7, RAMP = 0.14
      const below = lastY - (r.bottom - margin), above = (r.top + margin) - lastY
      if (below > 0) scroller.scrollTop += Math.min(MAX, below * RAMP)
      else if (above > 0 && scroller.scrollTop > 0) scroller.scrollTop -= Math.min(MAX, above * RAMP)
      // 2) EASE the real height toward the target at ≤ STEP px/frame — so a fast flick of the bar can't SNAP the
      //    card, growing OR shrinking. shrink used to be raw 1:1 pointer (twitchy); now it's throttled like grow.
      //    grow's target only climbs at the auto-scroll rate (≤MAX) so this cap never bottlenecks it — it just
      //    tames the fast free-pointer shrink. one knob to taste: STEP (px/frame, ~60fps → STEP*60 px/sec).
      const STEP = 10
      curH += Math.max(-STEP, Math.min(STEP, target() - curH))
      body.style.height = curH + 'px'
      raf = requestAnimationFrame(tick)
    }
    const move = ev => { lastY = ev.clientY }   // tick reads lastY + eases — no direct 1:1 resize on every mousemove
    const up = () => { cancelAnimationFrame(raf); document.removeEventListener('mousemove', move); document.removeEventListener('mouseup', up); document.body.style.userSelect = ''; document.body.classList.remove('resizing') }
    document.addEventListener('mousemove', move); document.addEventListener('mouseup', up)
    raf = requestAnimationFrame(tick)
  })
  return bar
}
window.OZ_CARD_BOTTOM = mkBottom   // settings (custom chrome) reuses the proven resize bar

