// helpers — HTML string → first node; append a Node / array / HTML string into a parent
function htmlNode(html) { const d = document.createElement('div'); d.innerHTML = html.trim(); return d.firstElementChild }
function into(parent, content) {
  if (!content) return
  if (typeof content === 'string') parent.innerHTML = content
  else if (Array.isArray(content)) content.forEach(c => parent.appendChild(c))
  else parent.appendChild(content)
}

